contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callers can't be changed here; we provide arrays to pass to transfer
    function run(address[] memory _tos, uint[] memory v) public payable {
        // ensure arrays lengths match to avoid index errors in external understanding
        require(_tos.length == v.length);

        // read observable state before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule:
        // If call did not revert, then msg.sender must have been the contract's hardcoded owner
        // and the _tos array had length > 0, and the public state variables 'from' and 'caddress' stayed the same.
        // If it reverted, at least one of those preconditions was not met.
        assert(
            // non-revert implies owner and non-empty and state unchanged
            (!reverted) == ((address(this) == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9) && (_tos.length > 0) && (c.from() == before_from) && (c.caddress() == before_caddress))
        );
    }

    receive() external payable { }
}

